// Generated by splitting tc/tests.rs into submodules for maintainability.

use super::*;

use crate::cert::ProofCert;
use crate::env::Declaration;

/// Helper: register `ZFC.Set : Type` as an axiom so that lambdas over
/// `ZFC.Set` can be type-inferred in tests (the domain needs a Sort type).
fn env_with_zfc_set() -> Environment {
    let mut env = Environment::new();
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("ZFC.Set"),
        level_params: vec![],
        type_: Expr::type_(),
    })
    .expect("registering ZFC.Set axiom");
    env
}

/// Helper: build a predicate `λ (x : ZFC.Set). x ∈ ∅` of type `ZFC.Set → Prop`.
fn zfc_set_to_prop_pred() -> Expr {
    use crate::expr::ZFCSetExpr;
    Expr::lam(
        BinderInfo::Default,
        Expr::const_(Name::from_string("ZFC.Set"), vec![]),
        Expr::from_kind(ExprKind::ZFCMem {
            element: std::sync::Arc::new(Expr::bvar(0)),
            set: std::sync::Arc::new(Expr::from_kind(ExprKind::ZFCSet(ZFCSetExpr::Empty))),
        }),
    )
}

/// Helper: build a function `λ (x : ZFC.Set). x` of type `ZFC.Set → ZFC.Set`.
fn zfc_set_identity() -> Expr {
    Expr::lam(
        BinderInfo::Default,
        Expr::const_(Name::from_string("ZFC.Set"), vec![]),
        Expr::bvar(0),
    )
}

#[test]
fn test_zfc_separation_type_check() {
    use crate::expr::ZFCSetExpr;
    use crate::mode::CleanMode;

    let env = env_with_zfc_set();
    let tc = TypeChecker::with_mode(&env, CleanMode::SetTheoretic);

    // Build {x ∈ A | φ(x)} where:
    // - A is the empty set
    // - φ is a predicate (ZFC.Set → Prop)
    let base_set = Expr::from_kind(ExprKind::ZFCSet(ZFCSetExpr::Empty));
    // Predicate: λ x : ZFC.Set. x ∈ ∅
    let pred = zfc_set_to_prop_pred();

    let separation = Expr::from_kind(ExprKind::ZFCSet(ZFCSetExpr::Separation {
        set: std::sync::Arc::new(base_set),
        pred: std::sync::Arc::new(pred),
    }));

    // Should type check successfully in SetTheoretic mode
    let result = tc.infer_type_with_cert(&separation);
    assert!(
        result.is_ok(),
        "Separation should type check in SetTheoretic mode: {result:?}"
    );

    // The type should be ZFC.Set
    let (ty, _cert) = result.unwrap();
    assert_eq!(
        ty,
        Expr::const_(Name::from_string("ZFC.Set"), vec![]),
        "Separation should have type ZFC.Set"
    );
}

#[test]
fn test_zfc_replacement_type_check() {
    use crate::expr::ZFCSetExpr;
    use crate::mode::CleanMode;

    let env = env_with_zfc_set();
    let tc = TypeChecker::with_mode(&env, CleanMode::SetTheoretic);

    // Build {F(x) | x ∈ A} where:
    // - A is the empty set
    // - F is a function (ZFC.Set → ZFC.Set)
    let base_set = Expr::from_kind(ExprKind::ZFCSet(ZFCSetExpr::Empty));
    // Function: λ x : ZFC.Set. x (identity on ZFC.Set)
    let func = zfc_set_identity();

    let replacement = Expr::from_kind(ExprKind::ZFCSet(ZFCSetExpr::Replacement {
        set: std::sync::Arc::new(base_set),
        func: std::sync::Arc::new(func),
    }));

    // Should type check successfully in SetTheoretic mode
    let result = tc.infer_type_with_cert(&replacement);
    assert!(
        result.is_ok(),
        "Replacement should type check in SetTheoretic mode: {result:?}"
    );

    // The type should be ZFC.Set
    let (ty, _cert) = result.unwrap();
    assert_eq!(
        ty,
        Expr::const_(Name::from_string("ZFC.Set"), vec![]),
        "Replacement should have type ZFC.Set"
    );
}

#[test]
fn test_zfc_separation_requires_set_theoretic_mode() {
    use crate::expr::ZFCSetExpr;

    let env = Environment::new();
    let tc = TypeChecker::new(&env); // Default Constructive mode

    let base_set = Expr::from_kind(ExprKind::ZFCSet(ZFCSetExpr::Empty));
    // Predicate: λ x : Prop. x
    let pred = Expr::lam(BinderInfo::Default, Expr::prop(), Expr::bvar(0));

    let separation = Expr::from_kind(ExprKind::ZFCSet(ZFCSetExpr::Separation {
        set: std::sync::Arc::new(base_set),
        pred: std::sync::Arc::new(pred),
    }));

    // Should be rejected in Constructive mode
    let result = tc.infer_type_with_cert(&separation);
    assert!(
        matches!(result, Err(TypeError::ModeRequired { .. })),
        "Separation should require SetTheoretic mode: {result:?}"
    );
}

